function longestPalindromeSubseq(s) {
  const n = s.length;
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let i = n - 1; i >= 0; i--) {
    dp[i][i] = 1;
    for (let j = i + 1; j < n; j++) {
      if (s[i] === s[j]) dp[i][j] = dp[i + 1][j - 1] + 2;
      else dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
    }
  }
  return dp[0][n - 1];
}

function longestRepeatingSubstring(s) {
  let ans = 0;
  const search = (len) => {
    const seen = new Set();
    let hash = 0, base = 256, mod = 100000007;
    for (let i = 0; i < len; i++) hash = (hash * base + s.charCodeAt(i)) % mod;
    seen.add(hash);
    let power = 1;
    for (let i = 1; i < len; i++) power = (power * base) % mod;
    for (let i = 1; i <= s.length - len; i++) {
      hash = (hash * base - s.charCodeAt(i - 1) * power + s.charCodeAt(i + len - 1)) % mod;
      if (hash < 0) hash += mod;
      if (seen.has(hash)) return true;
      seen.add(hash);
    }
    return false;
  };
  let l = 1, r = s.length;
  while (l <= r) {
    const mid = (l + r) >> 1;
    if (search(mid)) { ans = mid; l = mid + 1; }
    else r = mid - 1;
  }
  return ans;
}

function numDecodings(s) {
  if (!s || s[0] === '0') return 0;
  let prev = 1, curr = 1;
  for (let i = 1; i < s.length; i++) {
    const tmp = curr;
    if (s[i] === '0') curr = 0;
    if (s[i - 1] === '1' || (s[i - 1] === '2' && s[i] <= '6')) curr += prev;
    prev = tmp;
    if (!curr) return 0;
  }
  return curr;
}

function canJump(nums) {
  let farthest = 0;
  for (let i = 0; i < nums.length - 1; i++) {
    farthest = Math.max(farthest, i + nums[i]);
    if (farthest <= i) return false;
  }
  return farthest >= nums.length - 1;
}

function jump(nums) {
  let jumps = 0, currEnd = 0, farthest = 0;
  for (let i = 0; i < nums.length - 1; i++) {
    farthest = Math.max(farthest, i + nums[i]);
    if (i === currEnd) { jumps++; currEnd = farthest; }
  }
  return jumps;
}

function cloneGraph(node) {
  if (!node) return null;
  const map = new Map();
  const dfs = (n) => {
    if (map.has(n)) return map.get(n);
    const clone = new Node(n.val);
    map.set(n, clone);
    clone.neighbors = n.neighbors.map(dfs);
    return clone;
  };
  return dfs(node);
}

function findCircleNum(isConnected) {
  const n = isConnected.length;
  const visited = new Array(n).fill(false);
  let count = 0;
  const dfs = (i) => {
    visited[i] = true;
    for (let j = 0; j < n; j++)
      if (isConnected[i][j] && !visited[j]) dfs(j);
  };
  for (let i = 0; i < n; i++)
    if (!visited[i]) { count++; dfs(i); }
  return count;
}

