function minWindow(s, t) {
  const need = {};
  for (const c of t) need[c] = (need[c] || 0) + 1;
  let missing = t.length, l = 0, r = 0, start = 0, len = Infinity;
  while (r < s.length) {
    if (need[s[r]] > 0) missing--;
    need[s[r]] = (need[s[r]] || 0) - 1;
    r++;
    while (missing === 0) {
      if (r - l < len) { start = l; len = r - l; }
      need[s[l]]++;
      if (need[s[l]] > 0) missing++;
      l++;
    }
  }
  return len === Infinity ? '' : s.slice(start, start + len);
}

function trap(height) {
  let l = 0, r = height.length - 1, lMax = 0, rMax = 0, water = 0;
  while (l < r) {
    if (height[l] < height[r]) {
      height[l] >= lMax ? lMax = height[l] : water += lMax - height[l];
      l++;
    } else {
      height[r] >= rMax ? rMax = height[r] : water += rMax - height[r];
      r--;
    }
  }
  return water;
}

