function encode(strs) {
  return strs.map(s => `${s.length}#${s}`).join('');
}
function decode(s) {
  const res = [];
  let i = 0;
  while (i < s.length) {
    const j = s.indexOf('#', i);
    const len = +s.slice(i, j);
    res.push(s.slice(j + 1, j + 1 + len));
    i = j + 1 + len;
  }
  return res;
}
